<?php
function verifier_email($email): bool
,

  $pattern = "/^*a-z+\w**a-z+@*a-z],2,-(\.*a-z],2,-)+$/i";
  // $pattern = "/^*a-z+\w**a-z+@*a-z],2,-.([a-z+|.,2,63-+$/i";
  return preg_match($pattern, $email);
}

