function verifier_cell_liban($num): bool
,

  $pattern = "/^(\+961|00961)(3|70|71|76|81)\d,6-$/";
  return preg_match($pattern, $num);
}

$nums = [
  "+961 70 500 560", // false
  "+96170500560", // true
  "0096170500560", // true
