if ($_SERVER["REQUEST_METHOD"] == "POST") {
      if (!empty($_POST['nom']) && !empty($_POST['email']) && !empty($_POST['message'])) {
             $nom = htmlspecialchars(trim($_POST['nom']));
             $email = filter_var(trim($_POST['email']), FILTER_SANITIZE_EMAIL);
             $message = htmlspecialchars(trim($_POST['message']));

             if (filter_var($email, FILTER_VALIDATE_EMAIL)) {
                   $to = $email;
                   $subject = "Votre message a bien été reçu";
                   $body = "Cher {$nom},\n\nNous avons bien reçu votre message.\n\nVotre message

:\n{$message}\n\nCordialement,\nL'équipe";
                   $headers = "From: webmaster@cnam.fr\r\n";
                   $headers .= "Reply-To: webmaster@cnam.fr\r\n";
                   $headers .= "Content-Type: text/plain; charset=UTF-8\r\n";
                   if (mail($to, $subject, $body, $headers)) {
                          echo "Votre message a été envoyé avec succès.";
                   } else {
                          echo "Une erreur s'est produite lors de l'envoi de votre message.";
                   }

             } else {
                   echo "L'adresse e-mail fournie n'est pas valide.";

             }
      } else {

             echo "Veuillez remplir tous les champs obligatoires.";
      }
}
